{
  "name": "Yoctopuce 串口接口模块",
  "name_en": "Yoctopuce Serial Port Interface",
  "manufacturer": "Yoctopuce",
  "description": "用于控制 Yoctopuce 设备上的串口接口，可配置串口参数、协议和电平，并进行 ASCII、二进制及 MODBUS 通信。在实验室中可用于把上位机接入各类串口仪器、控制器或传感器。",
  "description_en": "A hardware serial port interface on a Yoctopuce device, used to configure serial parameters, protocols, and voltage levels, and to exchange ASCII, binary, and MODBUS data. In the lab, it can connect a host system to serial instruments, controllers, or sensors.",
  "tag_hints": [
    "serial communication",
    "UART",
    "MODBUS RTU",
    "ASCII/binary messaging",
    "RS-232/RS-485/TTL serial",
    "instrument integration"
  ],
  "actions": [
    {
      "action_name": "auto-set_currentJob",
      "description": "设置当前运行的作业文件。",
      "description_en": "set the current job file"
    },
    {
      "action_name": "auto-set_startupJob",
      "description": "设置上电启动时使用的作业文件。",
      "description_en": "set the startup job file"
    },
    {
      "action_name": "auto-set_command",
      "description": "设置命令字符串。",
      "description_en": "set the command string"
    },
    {
      "action_name": "auto-set_protocol",
      "description": "设置串口通信协议。",
      "description_en": "set the serial communication protocol"
    },
    {
      "action_name": "auto-set_voltageLevel",
      "description": "设置串口线路电平类型。",
      "description_en": "set the serial line voltage level"
    },
    {
      "action_name": "auto-set_serialMode",
      "description": "设置串口通信参数。",
      "description_en": "set the serial communication parameters"
    },
    {
      "action_name": "auto-sendCommand",
      "description": "向串口发送命令。",
      "description_en": "send a command to the serial port"
    },
    {
      "action_name": "auto-readLine",
      "description": "从接收缓冲区读取一行或一条消息。",
      "description_en": "read one line or message from the receive buffer"
    },
    {
      "action_name": "auto-readMessages",
      "description": "读取与指定模式匹配的接收消息。",
      "description_en": "read incoming messages matching a pattern"
    },
    {
      "action_name": "auto-read_seek",
      "description": "设置当前读取流位置。",
      "description_en": "set the current read stream position"
    },
    {
      "action_name": "auto-read_tell",
      "description": "获取当前读取流位置。",
      "description_en": "get the current read stream position"
    },
    {
      "action_name": "auto-read_avail",
      "description": "获取从当前位置起可读的字节数。",
      "description_en": "get the number of readable bytes from the current position"
    },
    {
      "action_name": "auto-queryLine",
      "description": "发送文本行查询并读取回复。",
      "description_en": "send a text line query and read the reply"
    },
    {
      "action_name": "auto-queryHex",
      "description": "发送十六进制二进制查询并读取回复。",
      "description_en": "send a hexadecimal binary query and read the reply"
    },
    {
      "action_name": "auto-uploadJob",
      "description": "上传 JSON 作业定义到设备作业文件。",
      "description_en": "upload a JSON job definition to a device job file"
    },
    {
      "action_name": "auto-selectJob",
      "description": "加载并启动指定作业文件。",
      "description_en": "load and start a job file"
    },
    {
      "action_name": "auto-reset",
      "description": "清空串口缓冲区并重置计数器。",
      "description_en": "clear the serial buffers and reset counters"
    },
    {
      "action_name": "auto-writeByte",
      "description": "向串口写入单个字节。",
      "description_en": "write a single byte to the serial port"
    },
    {
      "action_name": "auto-writeStr",
      "description": "向串口写入 ASCII 字符串。",
      "description_en": "write an ASCII string to the serial port"
    },
    {
      "action_name": "auto-writeBin",
      "description": "向串口写入二进制缓冲区。",
      "description_en": "write a binary buffer to the serial port"
    },
    {
      "action_name": "auto-writeArray",
      "description": "向串口写入字节数组。",
      "description_en": "write a byte array to the serial port"
    },
    {
      "action_name": "auto-writeHex",
      "description": "向串口写入十六进制字节序列。",
      "description_en": "write hexadecimal byte data to the serial port"
    },
    {
      "action_name": "auto-writeLine",
      "description": "向串口写入一行 ASCII 文本并附加换行。",
      "description_en": "write an ASCII line with line ending to the serial port"
    },
    {
      "action_name": "auto-readByte",
      "description": "从接收缓冲区读取单个字节。",
      "description_en": "read a single byte from the receive buffer"
    },
    {
      "action_name": "auto-readStr",
      "description": "从接收缓冲区读取字符串数据。",
      "description_en": "read string data from the receive buffer"
    },
    {
      "action_name": "auto-readBin",
      "description": "从接收缓冲区读取二进制数据。",
      "description_en": "read binary data from the receive buffer"
    },
    {
      "action_name": "auto-readArray",
      "description": "从接收缓冲区读取字节数组。",
      "description_en": "read a byte array from the receive buffer"
    },
    {
      "action_name": "auto-readHex",
      "description": "从接收缓冲区读取十六进制字符串数据。",
      "description_en": "read hexadecimal string data from the receive buffer"
    },
    {
      "action_name": "auto-set_RTS",
      "description": "设置 RTS 握手线状态。",
      "description_en": "set the RTS line state"
    },
    {
      "action_name": "auto-snoopMessages",
      "description": "旁路监视串口缓冲区中的双向消息。",
      "description_en": "snoop bidirectional messages in the serial buffer"
    },
    {
      "action_name": "auto-writeMODBUS",
      "description": "向串口发送 MODBUS 消息。",
      "description_en": "send a MODBUS message over the serial port"
    },
    {
      "action_name": "auto-queryMODBUS",
      "description": "向指定 MODBUS 从站发送请求并读取回复。",
      "description_en": "send a MODBUS request to a specified slave and read the reply"
    },
    {
      "action_name": "auto-modbusReadBits",
      "description": "读取 MODBUS 线圈状态位。",
      "description_en": "read MODBUS coil bits"
    },
    {
      "action_name": "auto-modbusReadInputBits",
      "description": "读取 MODBUS 离散输入位。",
      "description_en": "read MODBUS discrete input bits"
    },
    {
      "action_name": "auto-modbusReadRegisters",
      "description": "读取 MODBUS 保持寄存器。",
      "description_en": "read MODBUS holding registers"
    },
    {
      "action_name": "auto-modbusReadInputRegisters",
      "description": "读取 MODBUS 输入寄存器。",
      "description_en": "read MODBUS input registers"
    },
    {
      "action_name": "auto-modbusWriteBit",
      "description": "写入单个 MODBUS 线圈位。",
      "description_en": "write a single MODBUS coil bit"
    },
    {
      "action_name": "auto-modbusWriteBits",
      "description": "写入多个 MODBUS 线圈位。",
      "description_en": "write multiple MODBUS coil bits"
    },
    {
      "action_name": "auto-modbusWriteRegister",
      "description": "写入单个 MODBUS 保持寄存器。",
      "description_en": "write a single MODBUS holding register"
    },
    {
      "action_name": "auto-modbusWriteRegisters",
      "description": "写入多个 MODBUS 保持寄存器。",
      "description_en": "write multiple MODBUS holding registers"
    },
    {
      "action_name": "auto-modbusWriteAndReadRegisters",
      "description": "先写入后读取 MODBUS 寄存器。",
      "description_en": "write MODBUS registers and then read registers"
    },
    {
      "action_name": "auto-nextSerialPort",
      "description": "获取下一个可枚举的串口接口。",
      "description_en": "get the next enumerated serial port interface"
    }
  ]
}

